import{_ as s,C as n,o as t,c as i,E as r,a2 as l}from"./chunks/framework.Cm6XCzck.js";const k=JSON.parse('{"title":"Research Report Production Engine V2.0","description":"A recoverable Digital Research Employee production system built on Runtime Center V5, Scheduler V3.0, dependency-aware recovery, self-checks and GitHub First.","frontmatter":{"title":"Research Report Production Engine V2.0","description":"A recoverable Digital Research Employee production system built on Runtime Center V5, Scheduler V3.0, dependency-aware recovery, self-checks and GitHub First.","outline":"deep"},"headers":[],"relativePath":"en/publications/research-report-production-engine-v2.0.md","filePath":"en/publications/research-report-production-engine-v2.0.md","lastUpdated":1786259011000}'),o={name:"en/publications/research-report-production-engine-v2.0.md"};function p(d,e,c,h,u,m){const a=n("ArticleCover");return t(),i("div",null,[r(a,{image:"/assets/covers/research-report-production-engine-v1.svg",kicker:"Digital Employee Factory · Current Capability Release",title:"Research Report Production Engine V2.0",summary:"A dependency-driven, catch-up capable, recoverable and self-validating Digital Research Employee Runtime.",version:"V2.0",status:"2026-08-09 · Current Capability Release",languageHref:"/zh/publications/research-report-production-engine-v2.0",languageLabel:"中文"}),e[0]||(e[0]=l(`<h2 id="definition" tabindex="-1">Definition <a class="header-anchor" href="#definition" aria-label="Permalink to &quot;Definition&quot;">​</a></h2><p><strong>Research Report Production Engine V2.0</strong> is a GitHub-first Digital Research Employee Runtime whose research work is performed by ChatGPT workers. GitHub cron is a wake-up signal, not the source of operational truth. <code>SCHEDULER.json + Runtime Records</code> determine what is actually due. The runtime can detect missed shifts, recover from the earliest dependency-ready stage, reopen dependency-blocked work after its prerequisite completes, and validate both machine records and human-readable ledgers after state transitions.</p><h2 id="why-v2-0" tabindex="-1">Why V2.0 <a class="header-anchor" href="#why-v2-0" aria-label="Permalink to &quot;Why V2.0&quot;">​</a></h2><p>V1.x established a real production line spanning intelligence discovery, three-column triage, research skills, 15:00 Production, 20:00 Publication and GitHub Commit Verify. V2.0 addresses a different problem: <strong>how that production line remains correct when scheduling is delayed, historical results are heterogeneous, dependencies are incomplete, or a stage becomes blocked.</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>V1.x: time-triggered production line</span></span>
<span class="line"><span>              ↓</span></span>
<span class="line"><span>V2.0: dependency-driven recoverable runtime</span></span></code></pre></div><p>A cron occurrence is no longer treated as task truth, and a later stage may not jump over an incomplete prerequisite merely because its clock time has arrived.</p><h2 id="formal-daily-runtime" tabindex="-1">Formal Daily Runtime <a class="header-anchor" href="#formal-daily-runtime" aria-label="Permalink to &quot;Formal Daily Runtime&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>09:00 Discovery → Signal Pool</span></span>
<span class="line"><span>10:00 Queue → Today&#39;s Research Plan</span></span>
<span class="line"><span>11:00 Reading → Reading Result</span></span>
<span class="line"><span>13:00 Analysis → Research Object</span></span>
<span class="line"><span>15:00 Production → Publication Candidate</span></span>
<span class="line"><span>20:00 Publication → GitHub + Website + Commit Verify + Release</span></span></code></pre></div><p>Sunday adds a seventh task:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>20:30 Weekly → Weekly Synthesis</span></span></code></pre></div><p>A Sunday operational ledger therefore contains <strong>7 tasks</strong>.</p><h2 id="cron-is-a-wake-up-signal" tabindex="-1">Cron is a wake-up signal <a class="header-anchor" href="#cron-is-a-wake-up-signal" aria-label="Permalink to &quot;Cron is a wake-up signal&quot;">​</a></h2><p>Each Scheduler heartbeat re-derives work from durable facts:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SCHEDULER.json</span></span>
<span class="line"><span>+ Runtime Records</span></span>
<span class="line"><span>+ current Asia/Shanghai time</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>due shifts</span></span>
<span class="line"><span>+ durable statuses</span></span>
<span class="line"><span>+ completed prerequisites</span></span>
<span class="line"><span>+ dependency-blocked shifts now ready</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>open only the oldest runnable overdue shift</span></span></code></pre></div><p>The heartbeat minutes are offset from top-of-hour congestion. Missing one or more heartbeats delays work but does not expire it.</p><h2 id="strict-dependency-order" tabindex="-1">Strict dependency order <a class="header-anchor" href="#strict-dependency-order" aria-label="Permalink to &quot;Strict dependency order&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Discovery</span></span>
<span class="line"><span>→ Queue</span></span>
<span class="line"><span>→ Reading</span></span>
<span class="line"><span>→ Analysis</span></span>
<span class="line"><span>→ Production</span></span>
<span class="line"><span>→ Publication</span></span>
<span class="line"><span>→ Weekly (Sunday)</span></span></code></pre></div><p>Queue requires completed Discovery; Reading requires completed Queue; Analysis requires completed Reading; Production requires completed Analysis; Publication requires completed Production; Sunday Weekly requires completed Publication. A due time never overrides these gates.</p><h2 id="recoverable-blocked-state" tabindex="-1">Recoverable Blocked state <a class="header-anchor" href="#recoverable-blocked-state" aria-label="Permalink to &quot;Recoverable Blocked state&quot;">​</a></h2><p>A dependency-caused Blocked result records its prerequisite explicitly, for example:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;status&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Blocked&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;blockedBy&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;reading&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>After <code>reading</code> becomes <code>Completed</code>, Scheduler may use the governed <code>reopen-blocked</code> path to reopen Analysis. Ordinary Blocked states and Completed, Failed or Skipped work are not arbitrarily reopened.</p><h2 id="ordered-catch-up" tabindex="-1">Ordered catch-up <a class="header-anchor" href="#ordered-catch-up" aria-label="Permalink to &quot;Ordered catch-up&quot;">​</a></h2><p>Recovery follows this algorithm:</p><ol><li>enumerate today&#39;s tasks whose formal time has arrived;</li><li>read durable status for each task;</li><li>exclude Running, Completed, Failed and Skipped;</li><li>allow Waiting only when its prerequisite is Completed;</li><li>allow Blocked only when it is dependency-blocked and that dependency is now Completed;</li><li>sort by formal schedule time;</li><li>open <strong>one oldest runnable shift per heartbeat</strong>;</li><li>let later heartbeats continue catch-up.</li></ol><p>This prevents a multi-hour outage from reopening Reading, Analysis and Production concurrently.</p><h2 id="self-check-loop" tabindex="-1">Self-check loop <a class="header-anchor" href="#self-check-loop" aria-label="Permalink to &quot;Self-check loop&quot;">​</a></h2><p>Every opened or recovered slot must pass:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Runtime V5 validate</span></span>
<span class="line"><span>→ Markdown ledger render</span></span>
<span class="line"><span>→ Markdown ledger validate</span></span>
<span class="line"><span>→ durable Git commit</span></span>
<span class="line"><span>→ fetch / ancestor verify</span></span>
<span class="line"><span>→ taskStatus == Running verify</span></span>
<span class="line"><span>→ Execution Slot Opened event verify</span></span></code></pre></div><p>Terminal results still obey <code>runtime-shift-result/v2</code>: Input, Work Result, Output, Next, Metrics, Evidence and Artifacts. Runtime V5 accepts the legitimate flat bilingual and structured V5 result forms already present in the repository so historical valid results cannot break the scheduler control plane.</p><h2 id="human-readable-ledger-as-an-inspection-surface" tabindex="-1">Human-readable ledger as an inspection surface <a class="header-anchor" href="#human-readable-ledger-as-an-inspection-surface" aria-label="Permalink to &quot;Human-readable ledger as an inspection surface&quot;">​</a></h2><p>Machine JSON is authoritative; same-day Markdown is mandatory. Projection must correctly handle structured narratives, legacy metric names, string evidence/artifacts and object evidence/artifacts. <code>[object Object]</code>, fake Evidence placeholders, machine/Markdown status divergence, or missing start/terminal/Commit Verify events are projection failures.</p><h2 id="_2026-08-09-recovery-case" tabindex="-1">2026-08-09 Recovery Case <a class="header-anchor" href="#_2026-08-09-recovery-case" aria-label="Permalink to &quot;2026-08-09 Recovery Case&quot;">​</a></h2><p>On Sunday 2026-08-09, seven tasks were due. Discovery and Queue completed, but Reading was not opened correctly. Analysis later opened while Reading was incomplete and correctly produced a Blocked result. Investigation found a long gap in scheduled heartbeats, an incompatibility between Runtime V5 validation and already-valid structured shift results, a permanent-terminal interpretation of dependency Blocked, and a Markdown projection defect that rendered structured Queue results as <code>[object Object]</code>.</p><p>The recovery introduced result-contract compatibility, reopened Reading, marked Analysis with <code>blockedBy: reading</code>, added dependency gates and dependency-ready Blocked retry, repaired Markdown projection, and removed one-time hotfix machinery after the permanent implementation was installed.</p><p>The V2.0 recovery principle is therefore: <strong>restore facts first, restore the earliest dependency next, validate, then advance.</strong></p><h2 id="runtime-families" tabindex="-1">Runtime families <a class="header-anchor" href="#runtime-families" aria-label="Permalink to &quot;Runtime families&quot;">​</a></h2><p>V2.0 retains Runtime Center V5&#39;s four-family boundary: Daily, Weekly, Academic and Research Program Runtime. Program work does not consume Daily stages or column slots. Academic remains independent on Wednesday 16:00 and Program on Monday 12:00.</p><h2 id="authoritative-files" tabindex="-1">Authoritative files <a class="header-anchor" href="#authoritative-files" aria-label="Permalink to &quot;Authoritative files&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>research/runtime/SCHEDULER.json</span></span>
<span class="line"><span>research/runtime/records/{family}/YYYY/MM/*.json</span></span>
<span class="line"><span>research/runtime/YYYY/MM/YYYY-MM-DD-runtime.md</span></span>
<span class="line"><span>research/runtime/plans/YYYY/MM/YYYY-MM-DD-plan.json</span></span>
<span class="line"><span>scripts/runtime-v5.mjs</span></span>
<span class="line"><span>scripts/runtime-markdown.mjs</span></span>
<span class="line"><span>.github/workflows/research-runtime-scheduler.yml</span></span></code></pre></div><h2 id="download-and-validate" tabindex="-1">Download and validate <a class="header-anchor" href="#download-and-validate" aria-label="Permalink to &quot;Download and validate&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/joinwell52-AI/joinwell52.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> joinwell52</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> runtime:validate</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build</span></span></code></pre></div><p>Operational truth should be read from Runtime Center and the day&#39;s Markdown ledger, not inferred solely from whether an Actions run is green.</p><h2 id="v1-3-and-v2-0" tabindex="-1">V1.3 and V2.0 <a class="header-anchor" href="#v1-3-and-v2-0" aria-label="Permalink to &quot;V1.3 and V2.0&quot;">​</a></h2><p>V1.3 remains a historical capability release. V2.0 is the new Current Capability Release.</p><table tabindex="0"><thead><tr><th>Version</th><th>Runtime model</th></tr></thead><tbody><tr><td>V1.3</td><td>Research Intelligence + scheduled research production line</td></tr><tr><td><strong>V2.0</strong></td><td><strong>dependency-driven + overdue catch-up + Blocked recovery + self-validating Runtime</strong></td></tr></tbody></table><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>Reliability is not the promise that an external timer will always fire on time. It is the ability to reconstruct from durable facts what has completed, what is missing, what may run next, and how recovery itself is verified.</p>`,48))])}const y=s(o,[["render",p]]);export{k as __pageData,y as default};
